UPDATE seckill_goods
SET stock = stock - 1
WHERE id = #{productId}
AND stock = #{stock}

UPDATE seckill_goods
SET stock = stock + 1
WHERE id = #{goodsId}

UPDATE pms_product
SET stock = stock - #{quantity}
WHERE id = #{productId}
AND stock >= #{quantity}

UPDATE pms_product
SET stock = stock + #{quantity}
WHERE id = #{productId}
  AND #{quantity} > 0
